const qs = [
  ["picrep", "nl -ba AlgebraicJacobian/Picard/PicRepDatum.lean | sed -n '75,165p'; nl -ba AlgebraicJacobian/Picard/JacobianData.lean | sed -n '75,165p'; nl -ba AlgebraicJacobian/Picard/JacobianDataHandoff.lean | sed -n '25,90p'; nl -ba AlgebraicJacobian/Picard/JacobianDataFromPicRepDatum.lean | sed -n '60,115p'", "/home/axel/LeanAlgebraicGeometry-Horizon/MainProjects/Algebraic-Jacobian-Challenge-Rebuild"],
  ["global_rep_producers", "rg -n \"pic0.*[Rr]epresentableBy|RepresentableBy.*pic0|pic0_representableBy|picRepDatum.*C|JacobianData.*C\" AlgebraicJacobian/Picard AlgebraicJacobian/Descent --glob '*.lean' | sed -n '1,500p'", "/home/axel/LeanAlgebraicGeometry-Horizon/MainProjects/Algebraic-Jacobian-Challenge-Rebuild"],
  ["phase8_files", "rg -n \"^(noncomputable )?(def|theorem|lemma|abbrev|structure)|requires|hypothesis|conditional|sorry\" AlgebraicJacobian/AbelianVariety/AbelSource.lean AlgebraicJacobian/AbelianVariety/JacobianAbelianVariety.lean AlgebraicJacobian/AbelianVariety/JacobianSmooth.lean AlgebraicJacobian/AbelianVariety/RelativeDimensionLocal.lean AlgebraicJacobian/AbelianVariety/Translation.lean AlgebraicJacobian/AbelianVariety/GroupSeparated.lean AlgebraicJacobian/Albanese/Genus0Terminal.lean AlgebraicJacobian/Albanese/DescentUniqueness.lean AlgebraicJacobian/Tangent/Pic0TangentSpace.lean AlgebraicJacobian/Tangent/TangentCotangentCount.lean | sed -n '1,600p'", "/home/axel/LeanAlgebraicGeometry-Horizon/MainProjects/Algebraic-Jacobian-Challenge-Rebuild"]
];
const rs=await Promise.all(qs.map(async([name,cmd,workdir])=>{const r=await tools.exec_command({cmd,workdir,yield_time_ms:10000,max_output_tokens:40000});return{name,...r};}));
for(const r of rs) text(`=== ${r.name} ===\n${r.output}`);

