-\chapter{Sheaf cohomology and base change}
-\label{pa-ch-cohomology}
-
-\begin{definition}[Module-valued cohomology]
-  \label{pa-def-module-cohomology}
-  \dcref{III.1,custom}
-  \cite{stacks-project}
-  For a sheaf \(\mathcal F\) of \(k\)-modules on \(C\), put
-  \(H^i(C,\mathcal F)=\operatorname{Ext}^i(k_C,\mathcal F)\), with \(k_C\)
-  the constant sheaf.
-\end{definition}
-
-\begin{proposition}[The Cech short exact sequence]
-  \label{pa-prop-cech-short-exact}
-  \dcref{III.1}
-  \uses{pa-def-cech-complex,pa-lem-affine-vanishing}
-  \cite{stacks-project}
-  For \(C=U\cup V\) as above,
+\chapter{Degree-$g$ divisors and the rank-one Abel isomorphism}
+\label{route-ch-rank-one}
+
+Throughout this chapter the base field is an arbitrary field \(k\), and
+\(C/k\) satisfies H1--H2.  No separable-closedness or rational point is used.
+
+\section{The represented divisor package}
+
+\begin{theorem}[Represented widened divisors of degree \(g\)]
+  \label{route-thm-divisor-representer}
+  \lean{AlgebraicGeometry.divRepAffGenusScheme,
+    AlgebraicGeometry.divFunctorAff_genus_representableBy}
+  \leanok
+  \source{kleiman-picard}
+  \dcref{Theorem 3.7 and Exercise 3.8}
+  \uses{route-conv-objects}
+
+  Let \(\pi:C\to\mathbb P^1_k\) be the finite dominant map chosen internally
+  from H1--H2.  There is a \(k\)-scheme \(D_g\) and, naturally for every
+  \(T\to\Spec k\), a bijection
   \[
-    0\to\Gamma(C,\mathcal F)\to\mathcal F(U)\oplus\mathcal F(V)
-    \to\mathcal F(U\cap V)\to H^1(C,\mathcal F)\to0
+    \Hom_k(T,D_g)\;\simeq\;
+    \operatorname{divFunctorAff}(C,g)(T).
   \]
-  is exact.
-\end{proposition}
-
-\begin{proof}
-  The sheaf equalizer gives exactness at the first three terms, while affine
-  acyclicity identifies the cokernel with \(H^1\).
-\end{proof}
-
-\begin{definition}[Two-affine Cech complex]
-  \label{pa-def-cech-complex}
-  \dcref{III.1}
-  \cite{stacks-project}
-  For \(C=U\cup V\) with \(U,V,U\cap V\) affine, define
-  \[
-    \check C^0(\mathcal F)=\mathcal F(U)\oplus\mathcal F(V),\qquad
-    \check C^1(\mathcal F)=\mathcal F(U\cap V),
-  \]
-  with \(d(s,t)=s|_{U\cap V}-t|_{U\cap V}\).
-\end{definition}
-
-\begin{lemma}[Cech computes \(H^0\) and \(H^1\)]
-  \label{pa-lem-cech-computes}
-  \dcref{III.1}
-  \uses{pa-def-cech-complex}
-  \cite{stacks-project}
-  For quasi-coherent \(\mathcal F\),
-  \(H^0(C,\mathcal F)=\ker d\) and \(H^1(C,\mathcal F)=\operatorname{coker}d\).
-\end{lemma}
-
-\begin{proof}
-  Quasi-coherent sheaves are acyclic on affine opens and their intersections,
-  so the Cech-to-derived spectral sequence for this cover degenerates.
-\end{proof}
-
-\begin{lemma}[Affine cohomology vanishes]
-  \label{pa-lem-affine-vanishing}
-  \dcref{III.1}
-  \cite{stacks-project}
-  If \(W\) is affine and \(\mathcal F\) is quasi-coherent, then
-  \(H^i(W,\mathcal F)=0\) for \(i>0\).
-\end{lemma}
-
-\begin{proof}
-  For \(W=\Spec A\), write \(\mathcal F=\widetilde M\).  The section functor
-  is the exact identity on \(A\)-modules, so its positive derived functors
-  vanish.
-\end{proof}
-
-\begin{lemma}[Relative curves have cohomological dimension one]
-  \label{pa-lem-h2-vanishing}
-  \dcref{III.1}
-  \uses{pa-lem-cech-computes}
-  \cite{stacks-project}
-  For every \(T\) and quasi-coherent \(\mathcal F\) on \(C_T\),
-  \(H^i(C_T,\mathcal F)=0\) for \(i\ge2\).
-\end{lemma}
-
-\begin{proof}
-  Base change preserves a finite affine cover with affine finite intersections.
-  Its Cech complex has no terms in degrees above one.
-\end{proof}
-
-\begin{proposition}[Cech base change]
-  \label{pa-prop-cech-base-change}
-  \dcref{III.12}
-  \uses{pa-def-cech-complex}
-  \cite{stacks-project}
-  For \(k\subset k'\), the Cech complex of \(\mathcal F_{k'}\) is
-  \(\check C^\bullet(\mathcal F)\otimes_k k'\).
-\end{proposition}
+  The right side is the Lean widened divisor functor: compatible divisor
+  families on arbitrary affine opens, with the local certification used by
+  the finite-map/cohomology construction.  This statement must not be silently
+  replaced by representability of a differently defined divisor functor.
+\end{theorem}

 \begin{proof}
-  On affine opens, sections are modules; localization and tensor products
-  commute with the flat field extension.  The restriction maps are therefore
-  the scalar extensions of \(d\).
+  Kleiman's Theorem 3.7 represents relative effective divisors for a
+  projective flat family as an open of the Hilbert scheme, and Exercise 3.8
+  isolates fixed degree on a curve.  The Lean specialization chooses \(\pi\),
+  proves the required \(H^0\) and \(H^1\) finiteness and Euler-characteristic
+  identities from H1--H2, constructs the finite-relation affine charts, and
+  glues their classifiers.  At parameter \(g(C)\) this yields the displayed
+  `RepresentableBy` certificate on the exact functor
+  `divFunctorAff C (genus C)`.
 \end{proof}

-\begin{lemma}[Flat base change on cohomology]
-  \label{pa-lem-flat-cohomology}
-  \dcref{III.12}
-  \uses{pa-prop-cech-base-change,pa-lem-cech-computes}
-  \cite{stacks-project}
-  The natural map
-  \(H^i(C,\mathcal F)\otimes_k k'\to H^i(C_{k'},\mathcal F_{k'})\)
-  is an isomorphism.
-\end{lemma}
+\begin{remark}[The admissible divisor source is auxiliary]
+  \label{route-rem-admissible-source}
+  \lean{AlgebraicGeometry.divRepAffAdmissibleScheme,
+    AlgebraicGeometry.divFunctorAff_admissible_representableBy}
+  \leanok
+  \source{kleiman-picard}
+  \dcref{Definition 4.7 and proof of Theorem 4.8}
+  \uses{route-thm-divisor-representer}
+
+  Lean also constructs a quasi-compact represented divisor source in a larger
+  admissible degree.  In this route it is used only to prove quasi-compactness
+  of the final separably closed representer via a surjective Abel map.  Its
+  unrestricted Abel map is not the rank-one chart and is not quotiented to
+  construct \(J\).
+\end{remark}

 \begin{proof}
-  Tensoring with a field is exact, hence commutes with the kernel and cokernel
-  of the two-term Cech differential in \ref{pa-lem-cech-computes}.
+  The large degree kills \(H^1\) and supplies etale-local effective
+  representatives, exactly as in Kleiman's bounded Abel construction.  For
+  degree greater than \(g\), however, complete linear systems have positive
+  dimension; hence the unrestricted Abel map cannot be an open immersion.
 \end{proof}

-\begin{theorem}[Finiteness and base change]
-  \label{pa-thm-cohomology}
-  \dcref{III.12}
-  \uses{pa-def-genus}
-  \cite{stacks-project}
-  If \(\mathcal F\) is coherent on \(C\), then \(H^i(C,\mathcal F)\) is finite
-  dimensional over \(k\), and for every extension \(k\subset k'\),
+\section{The intrinsic rank-one open}
+
+\begin{theorem}[The rank-one Picard locus and its represented inverse image]
+  \label{route-thm-rank-one-open}
+  \lean{AlgebraicGeometry.PicRankOneLocalPresentation,
+    AlgebraicGeometry.PicRankOneOpen,
+    AlgebraicGeometry.picRankOneOpen_isOpen,
+    AlgebraicGeometry.DivRankOneOpenData,
+    AlgebraicGeometry.divRankOneOpenDataOfPicRankOneOpen}
+  \leanok
+  \source{kleiman-picard}
+  \dcref{proof of Theorem 4.8, cohomology-and-base-change open loci}
+  \uses{route-thm-divisor-representer}
+
+  For a test \(T/k\) and
+  \(\lambda\in\operatorname{Pic}^{g}_C(T)\), say that \(\lambda\) is
+  rank one precisely when
   \[
-    H^i(C,\mathcal F)\otimes_k k'\cong
-    H^i(C_{k'},\mathcal F_{k'}).
+    \forall(A,\,[\mathrm{CommRing}\ A],\,[\mathrm{Algebra}\ k\ A])\;
+    \forall t:\operatorname{Spec}_k A\longrightarrow T,\quad
+    \operatorname{Nonempty}\bigl(\operatorname{PicRankOneLocalPresentation}
+      (\pi,\lambda_t)\bigr),
+    \tag{R1P}
   \]
-\end{theorem}
-
-\begin{proof}
-  A finite affine cover of the proper curve gives a bounded Cech complex of
-  finite-dimensional \(k\)-vector spaces computing coherent cohomology.
-  Extending scalars tensors this complex with \(k'\); flatness of a field
-  extension commutes with its cohomology.  This proves both finiteness and the
-  displayed base-change isomorphism.
-\end{proof}
+  where \(\lambda_t\) is the functorial pullback of \(\lambda\).  A witness
+  in (R1P) is not an unnamed line bundle: it contains an etale cover
+  \(q:\operatorname{Spec}B\to\operatorname{Spec}A\), a descent-class
+  representative \(u\) with
+  \[
+    \operatorname{PicEtAff.mk}(u)=\operatorname{picEtAffineEquiv}(\lambda_t),
+  \]
