-  of \ref{pa-lem-degree-locally-constant}.
-\end{proof}
-
-\begin{lemma}[Translations between degree components]
-  \label{pa-lem-pic0-translation}
-  \dcref{5.1}
-  \uses{pa-prop-picard-group,pa-lem-degree-open-closed}
-  \cite{kleiman-picard}
-  Tensoring by a degree-\(r\) line bundle is an isomorphism
-  \(\operatorname{Pic}^d_{C/k}\cong\operatorname{Pic}^{d+r}_{C/k}\).
-\end{lemma}
-
-\begin{proof}
-  The tensor law adds degrees, and tensoring by the dual line bundle is the
-  inverse morphism.
-\end{proof}
-
-\begin{lemma}[Large-degree effective representatives]
-  \label{pa-lem-large-degree-effective}
-  \dcref{IV.1}
-  \uses{pa-thm-riemann-roch}
-  \cite{hartshorne-ag,papaioannou-rr}
-  If \(n\ge2g(C)-1\), every degree-\(n\) line bundle has a nonzero section and
-  is \(\mathcal O_C(D)\) for an effective divisor \(D\) of degree \(n\).
-\end{lemma}
-
-\begin{proof}
-  Riemann--Roch and the negative-degree vanishing give
-  \(h^0(C,\mathcal L)=n+1-g(C)>0\).  The zero divisor of a nonzero section
-  has the required degree and line bundle.
-\end{proof}
-
-\begin{lemma}[The Picard obstruction lies in \(H^2\)]
-  \label{pa-lem-picard-obstruction}
-  \dcref{5.11}
-  \uses{pa-lem-h2-vanishing}
-  \cite{kleiman-picard}
-  The obstruction to extending a line bundle across a square-zero thickening
-  is a class in \(H^2(C,\mathcal O_C)\).
-\end{lemma}
-
-\begin{proof}
-  Lift local trivializations and compare their transition functions.  The
-  failure of the lifted transitions to satisfy the cocycle condition is an
-  additive \(2\)-cocycle in \(\mathcal O_C\), whose class is the obstruction.
-\end{proof}
-
-\begin{proposition}[Smoothness of the identity component]
-  \label{pa-prop-pic0-smooth}
-  \dcref{5.11}
-  \uses{pa-lem-picard-obstruction,pa-lem-h2-vanishing,pa-prop-picard-group}
-  \cite{kleiman-picard}
-  \(\operatorname{Pic}^0_{C/k}\) is smooth.
-\end{proposition}
-
-\begin{proof}
-  The obstruction vanishes by \ref{pa-lem-h2-vanishing}, so the infinitesimal
-  lifting criterion gives smoothness at the identity.  Translations carry this
-  point to every point of the identity component.
-\end{proof}
-
-\begin{proposition}[Properness from a symmetric power]
-  \label{pa-prop-pic0-proper}
-  \dcref{5.4}
-  \uses{pa-lem-large-degree-effective,pa-prop-effective-map}
-  \cite{kleiman-picard}
-  \(\operatorname{Pic}^0_{C/k}\) is proper.
-\end{proposition}
-
-\begin{proof}
-  For \(n\ge2g(C)-1\), the proper scheme \(C^{(n)}\) maps surjectively to
-  \(\operatorname{Pic}^n_{C/k}\) by
-  \ref{pa-lem-large-degree-effective}.  Translating by a fixed degree-\(n\)
-  class identifies this component with \(\operatorname{Pic}^0_{C/k}\);
-  properness descends along the proper surjective Abel map.
-\end{proof}
-
-\begin{lemma}[Identity component is a subgroup]
-  \label{pa-lem-identity-component-subgroup}
-  \dcref{5.1}
-  \uses{pa-prop-picard-group,pa-def-pic0}
-  \cite{kleiman-picard}
-  The connected component of the identity in a group scheme locally of finite
-  type is an open-and-closed subgroup scheme.
-\end{lemma}
+\chapter{Universal class and finite-stage representability}
+\label{route-ch-universal}
+
+Chapter~\ref{route-ch-finite-stage} proves the carrier comparison for any
+legacy \(P_0:\operatorname{Pic0FiniteStageGluePackage}(C_\Omega,K)\).  The
+route does not freeze that arbitrary stage.  Instead, the first missing
+producer must choose a final legacy package only after all carrier, class, and
+cocycle coefficients have been enlarged to one finite Galois subextension.
+This joint choice is what prevents a silent change of carrier.
+
+\section{What is pinned over the separably closed field}
+
+\begin{theorem}[The universal class and all atlas restrictions over \(\Omega\)]
+  \label{route-thm-sepclosed-universal-class}
+  \lean{AlgebraicGeometry.pic0SepClosedUniversalClass,
+    AlgebraicGeometry.pic0FiniteStageUniversalChartClass,
+    AlgebraicGeometry.pic0FiniteStageUniversalOverlapClass,
+    AlgebraicGeometry.pic0FiniteStageUniversalChartClass_restrict_left,
+    AlgebraicGeometry.pic0FiniteStageUniversalChartClass_restrict_right,
+    AlgebraicGeometry.Pic0FiniteStageUniversalAtlasClass,
+    AlgebraicGeometry.pic0FiniteStageUniversalAtlasClass}
+  \leanok
+  \dcref{custom: Yoneda universal element and its restrictions}
+  \uses{route-thm-global-comparison}
+
+  Let
+  \[
+    \xi_\Omega:=r_\Omega(\mathrm{id}_{J_\Omega})
+       \in\operatorname{Pic}^0_{C_\Omega}(J_\Omega).
+  \]
+  For every selected affine chart \(U_i\subset J_\Omega\) and every selected
+  affine overlap \(U_{ij\alpha}\subset U_i\cap U_j\), the checked classes are
+  exactly the pullbacks of this one \(\xi_\Omega\).  If
+  \(q^i_{ij\alpha}:U_{ij\alpha}\to U_i\) and
+  \(q^j_{ij\alpha}:U_{ij\alpha}\to U_j\), then
+  \[
+    (q^i_{ij\alpha})^*(\xi_\Omega|_{U_i})
+      =\xi_\Omega|_{U_{ij\alpha}}
+      =(q^j_{ij\alpha})^*(\xi_\Omega|_{U_j}).
+  \]
+\end{theorem}

 \begin{proof}
-  Connected components are open in a locally Noetherian group scheme.
-  Multiplication and inversion preserve the component containing the identity,
-  while translations carry it to every other component.
+  Apply the representing equivalence to the identity of \(J_\Omega\).  Its
+  naturality says that precomposition by a chart or overlap morphism is
+  pullback of the resulting Picard class, proving both restriction equations.
+  Every class in this theorem still lives over \(\Omega\).
 \end{proof}

-\begin{lemma}[Geometric connectedness of the identity component]
-  \label{pa-lem-pic0-geometrically-connected}
-  \dcref{5.1}
-  \uses{pa-lem-identity-component-subgroup}
-  \cite{kleiman-picard}
-  The identity component of \(\operatorname{Pic}_{C/k}\) remains connected
-  after every field extension.
-\end{lemma}
+The source tree additionally declares \texttt{pic0ClassYoneda} and
+\texttt{pic0SepClosedClassYoneda\_app}, which express the expected
+class-to-natural-transformation formula.  Their defining module is not
+reachable from the public \texttt{AlgebraicJacobian} root and has no current
+verified artifact.  They are therefore unverified implementation aids, not
+attachments or proof credit in this specification.
+
+\section{The first unmet producer}
+
+\begin{theorem}[Joint Galois-stage package and descended universal class]
+  \label{route-thm-descended-universal-class}
+  \notready
+  \source{stacks-project}
+  \dcref{Tags 01ZM and 0EXM; Tag 0B9K as a source boundary}
+  \uses{route-thm-sepclosed-universal-class}
+
+  There must exist, simultaneously:
+  \begin{enumerate}
+  \item a legacy package
+    \(P:\operatorname{Pic0FiniteStageGluePackage}(C_\Omega,K)\);
+  \item for \(L:=P.N.1\subset\Omega\), certificates that \(L/K\) is finite
+    Galois, with the displayed inclusion and scalar-tower maps;
+  \item on the literal carrier \(J_L:=P.\mathrm{gluedOver}\), a class
+    \[
+      \xi_L\in\operatorname{Pic}^0_{C_L}(J_L)
+        =\operatorname{pic0Subgroup}
+          ((\operatorname{baseChange}_{K,L})C,P.\mathrm{gluedOver}),
+      \qquad C_L=C\times_KL.
+    \]
+  \end{enumerate}
+  The symbol \(P\) in this theorem is a new, jointly selected package; it is
+  not the arbitrary comparison witness \(P_0\) from
+  Theorem~\ref{route-thm-global-comparison}.  If the construction starts from
+  \(P_0\), it must additionally provide an explicit refinement map from
+  \(P_0\) to \(P\) together with the induced \(\operatorname{Over}\)-map and
+  its compatibility with every chart and overlap comparison.  Without those
+  fields, \(P_0\) is discarded after the comparison theorem and no field
+  enlargement is allowed to silently replace its carrier.  All subsequent
+  occurrences of \(J_L\), \(\xi_L\), (FS-Rep), (Proj), and (OA) quantify over
+  this single final \(P\).
+  For the checked comparison
+  \(\beta_P:J_L\times_L\Omega\xrightarrow{\sim}J_\Omega\), this class must
+  satisfy
+  \[
+    \operatorname{bc}_{L,\Omega}(\xi_L)=\beta_P^*(\xi_\Omega)
+      \quad\text{in}\quad
+    \operatorname{Pic}^0_{C_\Omega}(J_L\times_L\Omega).
+    \tag{UC}
+  \]
+  Equivalently, its restriction to every descended chart pulls back to
+  \(\xi_\Omega|_{U_i}\), and its two restrictions to every descended overlap
+  agree before gluing.
+\end{theorem}

 \begin{proof}
-  After base change to an algebraic closure, translations identify all
-  components.  The component containing the rational identity is therefore
-  geometrically connected, and descent gives the assertion.
+  The field-theoretic part has no route choice.  Every finite coefficient set
+  lies in a finite separable subextension because \(\Omega/K\) is algebraic
+  and separable.  Stacks Tag 0EXM places its finite normal closure \(L\) inside
+  \(\Omega\).  Only then re-run the finite-presentation descent of all chart
+  rings, restriction maps, inverse maps, and triple equations at \(L\), and
+  assemble the final legacy package with \(P.N.1=L\).  One must not retain an
+  earlier package while changing its field.
+
+  The unresolved mathematical step is to descend finite presentations of
+  representatives of the finitely many chart classes, all transition
+  isomorphisms and their cocycle equations at that same \(L\), glue them using
+  the actual etale-sheafified relative Picard equivalence relation, and prove
+  degree zero after every field-valued pullback.  Comparison through
+  \(\beta_P\) must then prove (UC).  Tag 01ZM supplies finite-presentation,
+  morphism, and equality descent.  Section 44.4 (Tag 0B9K) describes the fppf
+  Picard sheaf and invertible-sheaf descent, but is only orientation: it does
+  not identify that object with AJCR's big-etale degree-zero carrier or
+  construct \(\xi_L\).  The planned Lean handoff is one dependent package
+  containing exactly \(P\), the finite-Galois certificates, \(\xi_L\), and
+  equation (UC).
 \end{proof}

-\begin{lemma}[Dimension is the tangent dimension]
-  \label{pa-lem-pic0-dimension-tangent}
-  \dcref{5.11}
-  \uses{pa-prop-picard-tangent,pa-prop-pic0-smooth}
-  \cite{kleiman-picard}
-  For the smooth identity component,
-  \(\dim\operatorname{Pic}^0_{C/k}=\dim_kH^1(C,\mathcal O_C)=g(C)\).
-\end{lemma}
-
-\begin{proof}
-  A smooth finite-type scheme has dimension equal to the dimension of its
-  Zariski tangent space at a rational point.  Use the tangent identification
-  and the definition of \(g(C)\).
-\end{proof}
+\begin{theorem}[Yoneda equivalence on the same finite Galois carrier]
+  \label{route-thm-finite-stage-yoneda}
+  \notready
+  \source{stacks-project}
+  \dcref{Tag 040L, descent of morphisms; exact RepresentableBy target}
+  \uses{route-thm-descended-universal-class}

-\begin{definition}[Picard variety]
-  \label{pa-def-pic0}
-  \dcref{5.1}
-  \uses{pa-thm-picard-representability,pa-prop-picard-group}
-  \cite[Lem.~5.1]{kleiman-picard}
-  Define
+  For the same \((P,L,\xi_L)\), every \(L\)-scheme \(T\) must admit the
+  bijection
   \[
-    \operatorname{Pic}^0_{C/k}:=(\operatorname{Pic}_{C/k})^0,
+    \Phi_T:\Hom_L(T,J_L)\xrightarrow{\sim}
+       \operatorname{Pic}^0_{C_L}(T),
+    \qquad f\longmapsto f^*\xi_L.
+    \tag{Y}
   \]
-  the connected component containing the trivial line bundle.
-\end{definition}
-
-The degree is locally constant in a flat family, so the identity component is
-contained in the degree-zero component.  The Abel map for sufficiently large
-degree shows that these components differ only by translation.
-
-\begin{theorem}[Picard variety is an abelian variety]
-  \label{pa-thm-pic0-abelian}
-  \dcref{5.4,5.11,5.13,5.14}
-  \uses{pa-def-pic0,pa-prop-picard-tangent,pa-def-genus}
-  \cite[Thm.~5.4 and Cors.~5.13--5.14]{kleiman-picard}
-  The scheme \(\operatorname{Pic}^0_{C/k}\) is a smooth proper commutative
-  geometrically connected group scheme, hence an abelian variety, and
+  For every \(q:T'\to T\) and \(f:T\to J_L\), it must satisfy the correctly
+  typed naturality equation
   \[
-    \dim\operatorname{Pic}^0_{C/k}=g(C).
+    \Phi_{T'}(f\circ q)=q^*\Phi_T(f).
+  \]
+  The exact public Lean handoff is
+  \[
+    \operatorname{RepresentableBy}
+      (\operatorname{pic0TypeFunctor}(C_L),P.\mathrm{gluedOver}).
+    \tag{FS-Rep}
   \]
 \end{theorem}

 \begin{proof}
-  For \(n>2g(C)-2\), Riemann--Roch gives \(H^1(C,\mathcal L)=0\) for every
-  line bundle of degree \(n\).  The proper symmetric power \(C^{(n)}\) maps
-  surjectively to \(\operatorname{Pic}^n_{C/k}\); translating by a fixed
-  degree-\(n\) class proves that \(\operatorname{Pic}^0_{C/k}\) is proper.
-  Its tangent space is \(H^1(C,\mathcal O_C)\), while
-  \(H^2(C,\mathcal O_C)=0\) removes the obstruction to lifting line bundles
-  across square-zero thickenings.  Thus it is smooth at the identity and,
-  by translation, everywhere.  The identity-component theorem gives
-  geometric connectedness and the group structure, so it is an abelian
-  variety of dimension \(g(C)\).
+  Pullback of \(\xi_L\) defines the transformation in (Y).  To prove every
+  component bijective, compare it after the faithfully flat extension
+  \(L\to\Omega\).  Equation (UC), \(\beta_P\), and \(r_\Omega\) identify the
+  result with a bijection.  Existence and equality of morphisms then descend;
+  Stacks Remark 35.35.12 (Tag 040L) supplies the abstract fpqc morphism-descent
+  principle.  The specialization must be performed uniformly for arbitrary
+  \(T\), including the curve scalar-tower and big-etale degree-zero transports.
+
+  No public-root declaration proves (Y) or (FS-Rep).  In particular,
+  \texttt{pic0RepresentableBy\_finiteStageBaseChange} has target over
+  \(\Omega\), not over \(L\), and its own module is unrooted.
 \end{proof}

-\begin{proposition}[Degree-zero characterisation]
-  \label{pa-prop-pic0-degree}
-  \dcref{5.3}
-  \uses{pa-def-pic0}
-  \cite{kleiman-picard}
-  A geometric point of \(\operatorname{Pic}_{C/k}\) lies in
-  \(\operatorname{Pic}^0_{C/k}\) exactly when its line bundle has degree zero.
-\end{proposition}
-
-\begin{proof}
-  Degree is constant on connected components, so \(\operatorname{Pic}^0\) is
-  contained in the degree-zero locus.  Conversely, after an algebraic
-  closure, any degree-zero class can be written as
-  \([\mathcal O_C(D-nP_0)]\) for \(n\) sufficiently large by
-  Riemann--Roch.  It lies in the component of the identity, and descent from
-  the algebraic closure gives the assertion over \(k\).
-\end{proof}
+\begin{remark}[Frontier accounting]
+  \label{route-rem-first-frontier}
+  \dcref{custom}
+  \uses{route-thm-finite-stage-yoneda}
+
+  The first unmet mathematical producer is the class \(\xi_L\) and equation
+  (UC) in Theorem~\ref{route-thm-descended-universal-class}.  Choosing the
+  finite normal coefficient field and rebuilding the finite diagram there is
+  a fixed imported/planned prelude inside that same package, not a competing
+  route.  The frontier moves only when a class on the displayed literal
+  carrier exists; further transport or comparison wrappers do not move it.
+\end{remark}

